"""Gzip web/index.html into PillDispenserPro/web_page.h (run after editing the web page)."""
import gzip
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "web" / "index.html"
dst = root / "PillDispenserPro" / "web_page.h"

html = src.read_bytes()
gz = gzip.compress(html, compresslevel=9, mtime=0)
lines = []
for i in range(0, len(gz), 20):
    lines.append("  " + ",".join(f"0x{b:02x}" for b in gz[i:i + 20]) + ",")
dst.write_text(
    "// Generated by tools/build_web.py from web/index.html - do not edit\n"
    "#pragma once\n#include <Arduino.h>\n"
    f"static const size_t INDEX_GZ_LEN = {len(gz)};\n"
    "static const uint8_t INDEX_GZ[] PROGMEM = {\n" + "\n".join(lines) + "\n};\n",
    encoding="ascii",
)
print(f"{src.name}: {len(html)} bytes -> {len(gz)} bytes gzipped -> {dst.relative_to(root)}")
sys.exit(0)
